## Task 3: User Preferences API

**Files:**
- Create: `src/app/api/user/preferences/route.ts`

**Step 1: Create the API route**

```typescript
import { NextResponse } from 'next/server'
import { prisma } from '@/lib/db'
import { getDefaultUser } from '@/lib/user'

const VALID_LEVELS = ['undergraduate', 'masters', 'phd'] as const

/**
 * GET /api/user/preferences
 * Get current user preferences
 */
export async function GET() {
  try {
    const user = await getDefaultUser()
    return NextResponse.json({
      success: true,
      data: {
        readingLevel: user.readingLevel ?? 'undergraduate',
      },
    })
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to load preferences'
    return NextResponse.json({ success: false, error: message }, { status: 500 })
  }
}

/**
 * PUT /api/user/preferences
 * Update user preferences
 */
export async function PUT(req: Request) {
  try {
    const body = await req.json()
    const { readingLevel } = body

    // Validate readingLevel - reject undefined, null, empty, or invalid values
    if (
      readingLevel === undefined ||
      readingLevel === null ||
      readingLevel === '' ||
      !VALID_LEVELS.includes(readingLevel)
    ) {
      return NextResponse.json(
        { success: false, error: `Invalid readingLevel. Must be one of: ${VALID_LEVELS.join(', ')}` },
        { status: 400 }
      )
    }

    const user = await getDefaultUser()

    await prisma.user.update({
      where: { id: user.id },
      data: { readingLevel },
    })

    return NextResponse.json({ success: true })
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to update preferences'
    return NextResponse.json({ success: false, error: message }, { status: 500 })
  }
}
```

