## Task 4: Simplified Content Cache Check API

**Files:**
- Create: `src/app/api/section/[id]/simplified/route.ts`

**Step 1: Create the API route**

```typescript
import { NextResponse } from 'next/server'
import { prisma } from '@/lib/db'

const VALID_LEVELS = ['undergraduate', 'masters', 'phd'] as const
type ReadingLevel = (typeof VALID_LEVELS)[number]

/**
 * GET /api/section/[id]/simplified?level=undergraduate
 * Check if cached simplification exists
 */
export async function GET(req: Request, { params }: { params: { id: string } }) {
  try {
    const url = new URL(req.url)
    const level = (url.searchParams.get('level') ?? 'undergraduate') as ReadingLevel

    if (!VALID_LEVELS.includes(level)) {
      return NextResponse.json(
        { success: false, error: `Invalid level. Must be one of: ${VALID_LEVELS.join(', ')}` },
        { status: 400 }
      )
    }

    const cached = await prisma.simplifiedContent.findUnique({
      where: {
        sectionId_readingLevel: {
          sectionId: params.id,
          readingLevel: level,
        },
      },
      select: { content: true },
    })

    if (cached) {
      return NextResponse.json({
        success: true,
        data: { cached: true, content: cached.content },
      })
    }

    return NextResponse.json({
      success: true,
      data: { cached: false },
    })
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to check cache'
    return NextResponse.json({ success: false, error: message }, { status: 500 })
  }
}
```

