## Your Task: Simplified Content Streaming API

**File to create:** `src/app/api/section/[id]/simplified/stream/route.ts`

### Create the SSE streaming endpoint:

```typescript
import { prisma } from '@/lib/db'
import { loadPrompt } from '@/lib/prompts/registry'
import { generateText } from '@/lib/ai/azure'

const VALID_LEVELS = ['undergraduate', 'masters', 'phd'] as const
type ReadingLevel = (typeof VALID_LEVELS)[number]

interface StreamEvent {
  paragraph?: number
  text?: string
  total?: number
  done?: boolean
  error?: string
}

function createSSEStream() {
  const encoder = new TextEncoder()
  let controller: ReadableStreamDefaultController<Uint8Array>

  const stream = new ReadableStream<Uint8Array>({
    start(c) {
      controller = c
    },
  })

  function send(event: StreamEvent) {
    const data = `data: ${JSON.stringify(event)}\n\n`
    controller.enqueue(encoder.encode(data))
  }

  function close() {
    controller.close()
  }

  return { stream, send, close }
}

/**
 * GET /api/section/[id]/simplified/stream?level=undergraduate
 * Generate and stream simplified content paragraph by paragraph
 */
export async function GET(req: Request, { params }: { params: { id: string } }) {
  const url = new URL(req.url)
  const level = (url.searchParams.get('level') ?? 'undergraduate') as ReadingLevel

  if (!VALID_LEVELS.includes(level)) {
    return new Response(JSON.stringify({ error: 'Invalid level' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  const { stream, send, close } = createSSEStream()

  // Run generation in background
  ;(async () => {
    const simplifiedParagraphs: string[] = []

    try {
      // Load section content
      const section = await prisma.section.findUnique({
        where: { id: params.id },
        select: { sectionContent: true },
      })

      if (!section || !section.sectionContent) {
        send({ error: 'Section not found or has no content' })
        close()
        return
      }

      // Split into paragraphs (by double newline, cross-platform)
      const paragraphs = section.sectionContent
        .split(/\r?\n\r?\n+/)
        .map((p) => p.trim())
        .filter((p) => p.length > 0)

      send({ total: paragraphs.length })

      // Load prompt template
      const promptConfig = loadPrompt('simplify_section')

      // Process each paragraph
      for (let i = 0; i < paragraphs.length; i++) {
        const paragraph = paragraphs[i]

        const prompt = promptConfig.template
          .replaceAll('{level}', level)
          .replaceAll('{paragraph}', paragraph)

        const simplified = await generateText({
          prompt,
          maxTokens: 2048,
          temperature: 0.3,
        })

        simplifiedParagraphs.push(simplified.trim())
        send({ paragraph: i, text: simplified.trim() })
      }

      // All paragraphs completed successfully - save to cache
      const fullContent = simplifiedParagraphs.join('\n\n')

      await prisma.simplifiedContent.upsert({
        where: {
          sectionId_readingLevel: {
            sectionId: params.id,
            readingLevel: level,
          },
        },
        create: {
          sectionId: params.id,
          readingLevel: level,
          content: fullContent,
        },
        update: {
          content: fullContent,
        },
      })

      send({ done: true })
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Generation failed'
      send({ error: message })
    } finally {
      close()
    }
  })()

  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      Connection: 'keep-alive',
    },
  })
}
```

