import { prisma } from '@/lib/db'
import { getDefaultUser } from '@/lib/user'
import { NextResponse } from 'next/server'
import { PHASES } from '@/lib/constants'

interface RecallAnswers {
  mainClaim: string
  keyMechanism: string
  example: string
  modernParallel: string
  uncertainty: string
}

/**
 * GET /api/section/[id]/recall
 * Load saved recall answers for a section
 */
export async function GET(_req: Request, { params }: { params: { id: string } }) {
  try {
    const user = await getDefaultUser()

    const attempt = await prisma.sectionAttempt.findUnique({
      where: {
        userId_sectionId: {
          userId: user.id,
          sectionId: params.id,
        },
      },
      select: {
        blindRecall: true,
        blindSubmittedAt: true,
        currentPhase: true,
      },
    })

    if (!attempt || !attempt.blindRecall) {
      return NextResponse.json({
        success: true,
        data: {
          answers: null,
          submitted: false,
        },
      })
    }

    const answers = JSON.parse(attempt.blindRecall) as RecallAnswers

    return NextResponse.json({
      success: true,
      data: {
        answers,
        submitted: !!attempt.blindSubmittedAt,
        phase: attempt.currentPhase,
      },
    })
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to load recall answers'
    return NextResponse.json({ success: false, error: message }, { status: 500 })
  }
}

/**
 * PUT /api/section/[id]/recall
 * Save recall answers (autosave or explicit save)
 */
export async function PUT(req: Request, { params }: { params: { id: string } }) {
  try {
    const body = await req.json()
    const { answers, submit } = body as { answers: RecallAnswers; submit?: boolean }

    if (!answers) {
      return NextResponse.json({ success: false, error: 'answers required' }, { status: 400 })
    }

    const user = await getDefaultUser()

    // Verify section exists
    const section = await prisma.section.findUnique({
      where: { id: params.id },
    })

    if (!section) {
      return NextResponse.json({ success: false, error: 'Section not found' }, { status: 404 })
    }

    // Upsert SectionAttempt with recall answers
    const updateData: {
      blindRecall: string
      blindSubmittedAt?: Date
      currentPhase?: string
    } = {
      blindRecall: JSON.stringify(answers),
    }

    // If explicitly submitting, mark as submitted and advance phase
    if (submit) {
      updateData.blindSubmittedAt = new Date()
      updateData.currentPhase = PHASES.SUMMARY
    }

    await prisma.sectionAttempt.upsert({
      where: {
        userId_sectionId: {
          userId: user.id,
          sectionId: params.id,
        },
      },
      create: {
        userId: user.id,
        sectionId: params.id,
        blindRecall: JSON.stringify(answers),
        blindSubmittedAt: submit ? new Date() : null,
        currentPhase: submit ? PHASES.SUMMARY : PHASES.BLIND_RECALL,
      },
      update: updateData,
    })

    return NextResponse.json({
      success: true,
      data: {
        saved: true,
        submitted: !!submit,
      },
    })
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to save recall answers'
    return NextResponse.json({ success: false, error: message }, { status: 500 })
  }
}

