import { prisma } from '@/lib/db'
import { getDefaultUser } from '@/lib/user'
import { NextResponse } from 'next/server'

/**
 * GET /api/section/[id]/quiz
 * Load questions and any saved answers for this section
 */
export async function GET(_req: Request, { params }: { params: { id: string } }) {
  try {
    const user = await getDefaultUser()

    // Get questions for this section
    const questions = await prisma.question.findMany({
      where: { sectionId: params.id },
      orderBy: { orderIndex: 'asc' },
    })

    // Get existing quiz attempt if any
    const sectionAttempt = await prisma.sectionAttempt.findUnique({
      where: {
        userId_sectionId: {
          userId: user.id,
          sectionId: params.id,
        },
      },
      include: {
        quizAttempt: {
          include: {
            answers: true,
          },
        },
      },
    })

    // Format questions with saved answers
    const questionsWithAnswers = questions.map((q) => {
      const savedAnswer = sectionAttempt?.quizAttempt?.answers.find(
        (a) => a.questionId === q.id
      )

      return {
        id: q.id,
        questionType: q.questionType,
        questionSubtype: q.questionSubtype,
        questionText: q.questionText,
        options: q.options ? JSON.parse(q.options) : null,
        orderIndex: q.orderIndex,
        savedAnswer: savedAnswer?.userAnswer ?? null,
        feedback: savedAnswer?.feedbackJson ? JSON.parse(savedAnswer.feedbackJson) : null,
        score: savedAnswer?.score ?? null,
      }
    })

    return NextResponse.json({
      success: true,
      data: {
        questions: questionsWithAnswers,
        submitted: !!sectionAttempt?.quizAttempt?.submittedAt,
        totalScore: sectionAttempt?.quizAttempt?.totalScore ?? null,
      },
    })
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to load quiz'
    return NextResponse.json({ success: false, error: message }, { status: 500 })
  }
}

/**
 * PUT /api/section/[id]/quiz
 * Save quiz answers (autosave or submit for evaluation)
 */
export async function PUT(req: Request, { params }: { params: { id: string } }) {
  try {
    const body = await req.json()
    const { answers, submit } = body as {
      answers: Array<{ questionId: string; answer: string | number | number[] }>
      submit?: boolean
    }

    if (!answers || !Array.isArray(answers)) {
      return NextResponse.json({ success: false, error: 'answers required' }, { status: 400 })
    }

    const user = await getDefaultUser()

    // Get or create section attempt
    const sectionAttempt = await prisma.sectionAttempt.upsert({
      where: {
        userId_sectionId: {
          userId: user.id,
          sectionId: params.id,
        },
      },
      create: {
        userId: user.id,
        sectionId: params.id,
        currentPhase: 'quiz',
      },
      update: {},
    })

    // Get or create quiz attempt
    let quizAttempt = await prisma.quizAttempt.findUnique({
      where: { sectionAttemptId: sectionAttempt.id },
    })

    if (!quizAttempt) {
      quizAttempt = await prisma.quizAttempt.create({
        data: {
          sectionAttemptId: sectionAttempt.id,
          status: 'in_progress',
        },
      })
    }

    // Save each answer
    for (const ans of answers) {
      const answerValue =
        typeof ans.answer === 'object'
          ? JSON.stringify(ans.answer)
          : String(ans.answer)

      await prisma.quizAnswer.upsert({
        where: {
          quizAttemptId_questionId: {
            quizAttemptId: quizAttempt.id,
            questionId: ans.questionId,
          },
        },
        create: {
          quizAttemptId: quizAttempt.id,
          questionId: ans.questionId,
          userAnswer: answerValue,
        },
        update: {
          userAnswer: answerValue,
        },
      })
    }

    // If submitting, mark as submitted (evaluation happens separately)
    if (submit) {
      await prisma.quizAttempt.update({
        where: { id: quizAttempt.id },
        data: {
          status: 'submitted',
          submittedAt: new Date(),
        },
      })
    }

    return NextResponse.json({
      success: true,
      data: {
        saved: true,
        submitted: !!submit,
      },
    })
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to save quiz answers'
    return NextResponse.json({ success: false, error: message }, { status: 500 })
  }
}

import { prisma } from '@/lib/db'
import { getDefaultUser } from '@/lib/user'
import { loadPrompt } from '@/lib/prompts/registry'
import { generateText } from '@/lib/ai/azure'
import { parseQuizMarkdown } from '@/lib/prompts/quizParser'
import { PHASES } from '@/lib/constants'

interface ProgressEvent {
  step: number
  totalSteps: number
  message: string
  status: 'in_progress' | 'complete' | 'error'
  error?: string
}

function createSSEStream() {
  const encoder = new TextEncoder()
  let controller: ReadableStreamDefaultController<Uint8Array>

  const stream = new ReadableStream<Uint8Array>({
    start(c) {
      controller = c
    },
  })

  function send(event: ProgressEvent) {
    const data = `data: ${JSON.stringify(event)}\n\n`
    controller.enqueue(encoder.encode(data))
  }

  function close() {
    controller.close()
  }

  return { stream, send, close }
}

export async function POST(_req: Request, { params }: { params: { id: string } }) {
  const { stream, send, close } = createSSEStream()

  // Run generation in background, streaming progress
  ;(async () => {
    try {
      send({ step: 1, totalSteps: 5, message: 'Checking prerequisites...', status: 'in_progress' })

      const user = await getDefaultUser()

      const section = await prisma.section.findUnique({
        where: { id: params.id },
        include: { book: true },
      })

      if (!section || !section.book) {
        send({ step: 1, totalSteps: 5, message: 'Section not found', status: 'error', error: 'Section not found' })
        close()
        return
      }

      // Check if previous section is completed (if not section 1)
      if (section.sectionNumber > 1) {
        const previousSection = await prisma.section.findFirst({
          where: {
            bookId: section.bookId,
            sectionNumber: section.sectionNumber - 1,
          },
        })

        if (previousSection) {
          const previousAttempt = await prisma.sectionAttempt.findUnique({
            where: {
              userId_sectionId: {
                userId: user.id,
                sectionId: previousSection.id,
              },
            },
          })

          if (!previousAttempt || previousAttempt.currentPhase !== PHASES.COMPLETED) {
            send({
              step: 1,
              totalSteps: 5,
              message: 'Complete the previous section first',
              status: 'error',
              error: 'Previous section not completed',
            })
            close()
            return
          }
        }
      }

      // Create or get existing SectionAttempt
      await prisma.sectionAttempt.upsert({
        where: {
          userId_sectionId: {
            userId: user.id,
            sectionId: section.id,
          },
        },
        create: {
          userId: user.id,
          sectionId: section.id,
          currentPhase: PHASES.READ,
        },
        update: {}, // Don't update if already exists
      })

      send({ step: 2, totalSteps: 5, message: 'Generating summary...', status: 'in_progress' })

      const summaryPrompt = loadPrompt('summary')
      const summaryText = summaryPrompt.template
        .replaceAll('{book_title}', section.book.title)
        .replaceAll('{author}', section.book.author)
        .replaceAll('{section_id}', String(section.sectionNumber).padStart(3, '0'))
        .replaceAll('{section_title}', section.title)
        .replaceAll('{location}', section.location)
        .replaceAll('{source_text}', section.sectionContent ?? '')
        .replaceAll('{model}', process.env.AZURE_AI_MODEL ?? 'claude-opus-4-5')
        .replaceAll('{date}', new Date().toISOString().slice(0, 10))

      const summaryOut = await generateText({ prompt: summaryText })

      send({ step: 3, totalSteps: 5, message: 'Generating quiz questions...', status: 'in_progress' })

      const quizPrompt = loadPrompt('quiz')
      const quizText = quizPrompt.template
        .replaceAll('{book_title}', section.book.title)
        .replaceAll('{author}', section.book.author)
        .replaceAll('{section_id}', String(section.sectionNumber).padStart(3, '0'))
        .replaceAll('{section_title}', section.title)
        .replaceAll('{location}', section.location)
        .replaceAll('{summary_text}', summaryOut)
        .replaceAll('{source_text}', section.sectionContent ?? '')

      const quizOut = await generateText({ prompt: quizText })
      const parsed = parseQuizMarkdown(quizOut)

      send({ step: 4, totalSteps: 5, message: 'Saving content...', status: 'in_progress' })

      await prisma.section.update({
        where: { id: section.id },
        data: { summaryContent: summaryOut, contentVersion: { increment: 1 } },
      })

      if (parsed.length) {
        await prisma.question.deleteMany({ where: { sectionId: section.id } })
        await prisma.question.createMany({
          data: parsed.map((q, idx) => ({
            sectionId: section.id,
            questionType: q.questionType,
            questionSubtype: q.questionSubtype,
            questionText: q.questionText,
            options: q.options ? JSON.stringify(q.options) : null,
            correctAnswer: q.correctAnswer ?? null,
            orderIndex: idx + 1,
          })),
        })
      }

      send({ step: 5, totalSteps: 5, message: `Complete! Generated ${parsed.length} questions.`, status: 'complete' })
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Generation failed'
      send({ step: 0, totalSteps: 5, message, status: 'error', error: message })
    } finally {
      close()
    }
  })()

  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      Connection: 'keep-alive',
    },
  })
}

export type ParsedQuestion = {
  questionType: 'mcq' | 'prose'
  questionSubtype: string
  questionText: string
  options?: string[]
  correctAnswer?: string
}

export function parseQuizMarkdown(markdown: string): ParsedQuestion[] {
  const blocks = markdown.split(/\n---\n/g)
  const questions: ParsedQuestion[] = []

  for (const block of blocks) {
    const mcqMatch = block.match(/\*\*Type:\*\*\s*(one|multiple|none)/i)
    if (mcqMatch) {
      const options = Array.from(block.matchAll(/-\s+[A-D]\)\s+(.+)/g)).map(m => m[1].trim())
      const correct = block.match(/\*\*Correct:\*\*\s*([^\n]+)/i)?.[1]?.trim()
      const lines = block.split('\n')
      const qLine = lines.find(line => line.trim() && !line.startsWith('###') && !line.startsWith('-') && !line.startsWith('**') && !line.startsWith('<'))
      questions.push({
        questionType: 'mcq',
        questionSubtype: mcqMatch[1].toLowerCase(),
        questionText: qLine?.trim() ?? '',
        options,
        correctAnswer: correct,
      })
      continue
    }

    const proseMatch = block.match(/\[Type:\s*(Adversarial|Comparative|Socratic|Synthesis)\]/i)
    if (proseMatch) {
      const lines = block.split('\n')
      const qLine = lines.find(line => line.trim() && !line.startsWith('###') && !line.startsWith('**'))
      questions.push({
        questionType: 'prose',
        questionSubtype: proseMatch[1].toLowerCase(),
        questionText: qLine?.trim() ?? '',
      })
    }
  }

  return questions
}

