import { NextResponse } from 'next/server'
import { prisma } from '@/lib/prisma'
import { parseQuizMarkdown } from '@/lib/prompts/quizParser'

export async function POST(req: Request, { params }: { params: { id: string } }) {
  const { id } = await params

  const section = await prisma.section.findUnique({
    where: { id },
    select: { id: true, rawQuizOutput: true },
  })

  if (!section) {
    return NextResponse.json({ error: 'Section not found' }, { status: 404 })
  }

  if (!section.rawQuizOutput) {
    return NextResponse.json({
      error: 'No raw quiz output stored. This quiz was generated before raw output storage was added. Please regenerate the quiz.',
      needsRegeneration: true
    }, { status: 400 })
  }

  // Re-parse with updated parser
  const parsed = parseQuizMarkdown(section.rawQuizOutput)
  console.log('[Reparse] Parsed questions:', parsed.map(q => ({ type: q.questionType, subtype: q.questionSubtype, text: q.questionText.substring(0, 50) })))

  // Delete existing questions and answers
  const existingQuestions = await prisma.question.findMany({
    where: { sectionId: section.id },
    select: { id: true },
  })
  if (existingQuestions.length > 0) {
    await prisma.quizAnswer.deleteMany({
      where: { questionId: { in: existingQuestions.map(q => q.id) } },
    })
  }
  await prisma.question.deleteMany({ where: { sectionId: section.id } })

  // Create new questions from re-parsed output
  if (parsed.length) {
    await prisma.question.createMany({
      data: parsed.map((q, idx) => ({
        sectionId: section.id,
        questionType: q.questionType,
        questionSubtype: q.questionSubtype,
        questionText: q.questionText,
        options: q.options ? JSON.stringify(q.options) : null,
        correctAnswer: q.correctAnswer ?? null,
        orderIndex: idx + 1,
      })),
    })
  }

  return NextResponse.json({
    success: true,
    questionCount: parsed.length,
    questions: parsed.map(q => ({ type: q.questionType, subtype: q.questionSubtype }))
  })
}

