import { prisma } from '@/lib/db'
import { getDefaultUser } from '@/lib/user'
import { NextResponse } from 'next/server'
import { generateText } from '@/lib/ai/azure'
import { loadPrompt } from '@/lib/prompts/registry'
import { PHASES } from '@/lib/constants'

interface RecallAnswers {
  mainClaim: string
  keyMechanism: string
  example: string
  modernParallel: string
  uncertainty: string
}

interface EvaluationResult {
  recall?: {
    points: Array<{
      label: string
      correct: boolean
      accuracy: string
      reasoning: string
      writing: string
    }>
    one_sentence_ok: boolean
    one_sentence_note: string
    score: number
    reasoning: string
  }
  quiz?: {
    answers: Array<{
      question_id: string
      label: string
      score: number
      errors: Array<{
        quoted_text: string
        summary: string
        feedback: string
      }>
      writing_note: string | null
    }>
    total_score: number
    thematic_insights: {
      source_mastery: string
      reasoning_quality: string
      writing_craft: {
        precision: number
        clarity: number
        economy: number
        suggestion: string
      }
    }
    tutors_note: string
  }
}

/**
 * POST /api/section/[id]/evaluate
 * Evaluate recall and quiz answers using AI
 */
export async function POST(_req: Request, { params }: { params: { id: string } }) {
  try {
    const user = await getDefaultUser()

    // Get section with content
    const section = await prisma.section.findUnique({
      where: { id: params.id },
      include: { book: true },
    })

    if (!section) {
      return NextResponse.json({ success: false, error: 'Section not found' }, { status: 404 })
    }

    // Get section attempt with recall and quiz data
    const sectionAttempt = await prisma.sectionAttempt.findUnique({
      where: {
        userId_sectionId: {
          userId: user.id,
          sectionId: params.id,
        },
      },
      include: {
        quizAttempt: {
          include: {
            answers: {
              include: { question: true },
            },
          },
        },
      },
    })

    if (!sectionAttempt) {
      return NextResponse.json(
        { success: false, error: 'No attempt found for this section' },
        { status: 400 }
      )
    }

    // Parse recall answers
    let recallAnswers: RecallAnswers | null = null
    if (sectionAttempt.blindRecall) {
      recallAnswers = JSON.parse(sectionAttempt.blindRecall)
    }

    // Format recall points for the prompt
    const recallPointsFormatted = recallAnswers
      ? `
1. Main Claim: ${recallAnswers.mainClaim || '(not answered)'}
2. Key Mechanism: ${recallAnswers.keyMechanism || '(not answered)'}
3. Example I Remember: ${recallAnswers.example || '(not answered)'}
4. Modern Parallel: ${recallAnswers.modernParallel || '(not answered)'}
5. Uncertainty: ${recallAnswers.uncertainty || '(not answered)'}
`.trim()
      : '(No recall submitted)'

    // Format quiz answers for the prompt
    const quizAnswersFormatted = sectionAttempt.quizAttempt?.answers
      .map((a) => {
        const q = a.question
        return `
Question ${q.orderIndex} (${q.questionType}/${q.questionSubtype}): ${q.questionText}
${q.options ? `Options: ${q.options}` : ''}
${q.correctAnswer ? `Correct Answer: ${q.correctAnswer}` : ''}
Student's Answer: ${a.userAnswer || '(not answered)'}
`.trim()
      })
      .join('\n\n') || '(No quiz answers submitted)'

    // Load and render the evaluation prompt
    const evalPrompt = loadPrompt('evaluation')
    const promptText = evalPrompt.template
      .replaceAll('{source_text}', section.sectionContent ?? '')
      .replaceAll('{recall_points_formatted}', recallPointsFormatted)
      .replaceAll('{one_sentence}', recallAnswers?.mainClaim ?? '(not provided)')
      .replaceAll('{quiz_answers_formatted}', quizAnswersFormatted)
      // Handle the partial expansion (double braces become single)
      .replaceAll('{{edps_intro}}', loadPrompt('summary').template.split('\n')[0] || '')

    console.log('[Evaluation] Calling AI for evaluation...')

    // Call AI for evaluation
    const aiResponse = await generateText({
      prompt: promptText,
      maxTokens: 4096,
      temperature: 0.3,
    })

    // Parse the JSON response
    let evaluation: EvaluationResult
    try {
      // Extract JSON from response (it might have markdown code blocks)
      const jsonMatch = aiResponse.match(/```json\s*([\s\S]*?)\s*```/) ||
        aiResponse.match(/\{[\s\S]*\}/)
      const jsonStr = jsonMatch ? (jsonMatch[1] || jsonMatch[0]) : aiResponse
      evaluation = JSON.parse(jsonStr)
    } catch {
      console.error('[Evaluation] Failed to parse AI response:', aiResponse)
      return NextResponse.json(
        { success: false, error: 'Failed to parse evaluation response' },
        { status: 500 }
      )
    }

    // Save recall feedback
    if (evaluation.recall) {
      await prisma.sectionAttempt.update({
        where: { id: sectionAttempt.id },
        data: {
          recallFeedbackJson: JSON.stringify(evaluation.recall),
          recallScore: evaluation.recall.score,
          recallEvaluatedAt: new Date(),
          recallModelId: process.env.AZURE_AI_MODEL ?? 'claude-sonnet-4-20250514',
          recallPromptVersion: '1',
          missedPoints: JSON.stringify(
            evaluation.recall.points
              .filter((p) => !p.correct)
              .map((p) => ({ label: p.label, feedback: p.accuracy }))
          ),
        },
      })
    }

    // Save quiz feedback
    if (evaluation.quiz && sectionAttempt.quizAttempt) {
      // Update each quiz answer with feedback
      for (const answerFeedback of evaluation.quiz.answers) {
        const existingAnswer = sectionAttempt.quizAttempt.answers.find(
          (a) => a.question.orderIndex.toString() === answerFeedback.question_id.replace('q', '')
        )
        if (existingAnswer) {
          await prisma.quizAnswer.update({
            where: { id: existingAnswer.id },
            data: {
              score: answerFeedback.score,
              feedbackJson: JSON.stringify({
                errors: answerFeedback.errors,
                writingNote: answerFeedback.writing_note,
              }),
              isCorrect: answerFeedback.score >= 1,
            },
          })
        }
      }

      // Update quiz attempt with overall scores
      await prisma.quizAttempt.update({
        where: { id: sectionAttempt.quizAttempt.id },
        data: {
          status: 'evaluated',
          totalScore: evaluation.quiz.total_score,
          thematicFeedbackJson: JSON.stringify(evaluation.quiz.thematic_insights),
          tutorNote: evaluation.quiz.tutors_note,
          evaluatedAt: new Date(),
          modelId: process.env.AZURE_AI_MODEL ?? 'claude-sonnet-4-20250514',
          promptVersion: '1',
        },
      })
    }

    // Advance to feedback phase
    await prisma.sectionAttempt.update({
      where: { id: sectionAttempt.id },
      data: { currentPhase: PHASES.FEEDBACK },
    })

    console.log('[Evaluation] Complete')

    return NextResponse.json({
      success: true,
      data: {
        recall: evaluation.recall,
        quiz: evaluation.quiz,
      },
    })
  } catch (err) {
    console.error('[Evaluation] Error:', err)
    const message = err instanceof Error ? err.message : 'Evaluation failed'
    return NextResponse.json({ success: false, error: message }, { status: 500 })
  }
}

/**
 * GET /api/section/[id]/evaluate
 * Get existing evaluation results
 */
export async function GET(_req: Request, { params }: { params: { id: string } }) {
  try {
    const user = await getDefaultUser()

    const sectionAttempt = await prisma.sectionAttempt.findUnique({
      where: {
        userId_sectionId: {
          userId: user.id,
          sectionId: params.id,
        },
      },
      include: {
        quizAttempt: {
          include: {
            answers: {
              include: { question: true },
            },
          },
        },
      },
    })

    if (!sectionAttempt) {
      return NextResponse.json({
        success: true,
        data: { evaluated: false },
      })
    }

    const recallFeedback = sectionAttempt.recallFeedbackJson
      ? JSON.parse(sectionAttempt.recallFeedbackJson)
      : null

    const quizFeedback = sectionAttempt.quizAttempt
      ? {
          totalScore: sectionAttempt.quizAttempt.totalScore,
          thematicInsights: sectionAttempt.quizAttempt.thematicFeedbackJson
            ? JSON.parse(sectionAttempt.quizAttempt.thematicFeedbackJson)
            : null,
          tutorNote: sectionAttempt.quizAttempt.tutorNote,
          answers: sectionAttempt.quizAttempt.answers.map((a) => ({
            questionId: a.questionId,
            questionText: a.question.questionText,
            userAnswer: a.userAnswer,
            score: a.score,
            feedback: a.feedbackJson ? JSON.parse(a.feedbackJson) : null,
          })),
        }
      : null

    const missedPoints = sectionAttempt.missedPoints
      ? JSON.parse(sectionAttempt.missedPoints)
      : null

    return NextResponse.json({
      success: true,
      data: {
        evaluated: !!sectionAttempt.recallEvaluatedAt || !!sectionAttempt.quizAttempt?.evaluatedAt,
        recall: recallFeedback
          ? {
              score: sectionAttempt.recallScore,
              feedback: recallFeedback,
            }
          : null,
        quiz: quizFeedback,
        missedPoints,
        phase: sectionAttempt.currentPhase,
      },
    })
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to get evaluation'
    return NextResponse.json({ success: false, error: message }, { status: 500 })
  }
}

'use client'

import { useState, useEffect, useRef, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { Phase, PHASES, canAccessPhase, getPhaseIndex } from '@/lib/constants'

type Tab = 'read' | 'recall' | 'summary' | 'revision' | 'quiz' | 'feedback'

// Map tabs to phases
const TAB_TO_PHASE: Record<Tab, Phase> = {
  read: PHASES.READ,
  recall: PHASES.BLIND_RECALL,
  summary: PHASES.SUMMARY,
  revision: PHASES.REVISION,
  quiz: PHASES.QUIZ,
  feedback: PHASES.FEEDBACK,
}

interface SectionTabsProps {
  sectionId: string
  sectionContent: string
  summaryContent: string
  initialPhase: Phase
}

interface RecallAnswers {
  mainClaim: string
  keyMechanism: string
  example: string
  modernParallel: string
  uncertainty: string
}

interface Question {
  id: string
  questionType: 'mcq' | 'prose'
  questionSubtype: string
  questionText: string
  options: string[] | null
  orderIndex: number
  savedAnswer: string | null
  feedback: { errors: Array<{ quoted_text: string; summary: string; feedback: string }>; writingNote: string | null } | null
  score: number | null
}

interface EvaluationData {
  evaluated: boolean
  recall?: {
    score: number
    feedback: {
      points: Array<{ label: string; correct: boolean; accuracy: string; reasoning: string }>
      one_sentence_ok: boolean
      one_sentence_note: string
      reasoning: string
    }
  }
  quiz?: {
    totalScore: number
    thematicInsights: {
      source_mastery: string
      reasoning_quality: string
      writing_craft: { precision: number; clarity: number; economy: number; suggestion: string }
    }
    tutorNote: string
    answers: Array<{
      questionId: string
      questionText: string
      userAnswer: string
      score: number
      feedback: { errors: Array<{ quoted_text: string; summary: string; feedback: string }>; writingNote: string | null } | null
    }>
  }
  missedPoints?: Array<{ label: string; feedback: string }>
}

type SaveStatus = 'idle' | 'saving' | 'saved' | 'error'
type ReadView = 'original' | 'simplified'
type SimplifyStatus = 'idle' | 'loading' | 'ready' | 'error'

const TABS: { id: Tab; label: string; phase: Phase }[] = [
  { id: 'read', label: 'READ', phase: PHASES.READ },
  { id: 'recall', label: 'RECALL', phase: PHASES.BLIND_RECALL },
  { id: 'summary', label: 'SUMMARY', phase: PHASES.SUMMARY },
  { id: 'revision', label: 'REVISION', phase: PHASES.REVISION },
  { id: 'quiz', label: 'QUIZ', phase: PHASES.QUIZ },
  { id: 'feedback', label: 'FEEDBACK', phase: PHASES.FEEDBACK },
]

const RECALL_PROMPTS = [
  { id: 'mainClaim' as const, title: '1. Main Claim', question: 'What was the core argument? Write it in your own words.', placeholder: 'The author argues that...' },
  { id: 'keyMechanism' as const, title: '2. Key Mechanism', question: 'What process or cause-effect relationship was described?', placeholder: 'This happens because... which leads to...' },
  { id: 'example' as const, title: '3. Example I Remember', question: 'What example stuck with you?', placeholder: 'The author illustrated this with...' },
  { id: 'modernParallel' as const, title: '4. Modern Parallel', question: 'What connection to today came to mind while reading?', placeholder: 'This reminds me of how today...' },
  { id: 'uncertainty' as const, title: '5. Uncertainty', question: 'What am I unsure about or confused by?', placeholder: "I'm not sure about... or I wonder if..." },
]

const REVISION_PROMPTS = [
  { id: 'forgottenPoints' as const, title: '1. Forgotten Points', question: 'What key points did you forget?', placeholder: 'I forgot to mention...' },
  { id: 'misremembered' as const, title: '2. Misremembered Concepts', question: 'Were there concepts you misremembered?', placeholder: 'I thought... but actually...' },
  { id: 'missedExamples' as const, title: '3. Missed Examples', question: 'Which examples did you miss?', placeholder: 'The author also mentioned...' },
]

type RevisionAnswers = { forgottenPoints: string; misremembered: string; missedExamples: string }
const EMPTY_REVISION_ANSWERS: RevisionAnswers = { forgottenPoints: '', misremembered: '', missedExamples: '' }

const EMPTY_ANSWERS: RecallAnswers = { mainClaim: '', keyMechanism: '', example: '', modernParallel: '', uncertainty: '' }
const AUTOSAVE_DELAY_MS = 1500

export default function SectionTabs({ sectionId, sectionContent, summaryContent, initialPhase }: SectionTabsProps) {
  const router = useRouter()

  // Phase state - determines which tabs are accessible
  const [currentPhase, setCurrentPhase] = useState<Phase>(initialPhase)
  const [activeTab, setActiveTab] = useState<Tab>(getInitialTab(initialPhase))

  // Recall state
  const [recallAnswers, setRecallAnswers] = useState<RecallAnswers>(EMPTY_ANSWERS)
  const [recallSaveStatus, setRecallSaveStatus] = useState<SaveStatus>('idle')
  const [isRecallSubmitted, setIsRecallSubmitted] = useState(false)
  const [isRecallLoading, setIsRecallLoading] = useState(true)

  // Revision state
  const [revisionAnswers, setRevisionAnswers] = useState<RevisionAnswers>(EMPTY_REVISION_ANSWERS)
  const [revisionSaveStatus, setRevisionSaveStatus] = useState<SaveStatus>('idle')
  const [isRevisionSubmitted, setIsRevisionSubmitted] = useState(false)
  const [isRevisionLoading, setIsRevisionLoading] = useState(true)

  // Quiz state
  const [questions, setQuestions] = useState<Question[]>([])
  const [quizAnswers, setQuizAnswers] = useState<Record<string, string>>({})
  const [quizSaveStatus, setQuizSaveStatus] = useState<SaveStatus>('idle')
  const [isQuizSubmitted, setIsQuizSubmitted] = useState(false)
  const [isQuizLoading, setIsQuizLoading] = useState(true)

  // Evaluation state
  const [evaluation, setEvaluation] = useState<EvaluationData | null>(null)
  const [isEvaluating, setIsEvaluating] = useState(false)

  // Read view state
  const [readView, setReadView] = useState<ReadView>('original')
  const [simplifyStatus, setSimplifyStatus] = useState<SimplifyStatus>('idle')
  const [simplifiedContent, setSimplifiedContent] = useState<string>('')
  const [simplifiedParagraphs, setSimplifiedParagraphs] = useState<string[]>([])
  const [totalParagraphs, setTotalParagraphs] = useState(0)
  const [readingLevel, setReadingLevel] = useState<string>('undergraduate')
  const [simplifyError, setSimplifyError] = useState<string | null>(null)

  // Ref for EventSource cleanup
  const eventSourceRef = useRef<EventSource | null>(null)

  // Refs
  const recallSaveTimerRef = useRef<NodeJS.Timeout | null>(null)
  const revisionSaveTimerRef = useRef<NodeJS.Timeout | null>(null)
  const quizSaveTimerRef = useRef<NodeJS.Timeout | null>(null)
  const recallInitialLoadRef = useRef(true)
  const revisionInitialLoadRef = useRef(true)
  const quizInitialLoadRef = useRef(true)

  function getInitialTab(phase: Phase): Tab {
    const phaseToTab: Record<Phase, Tab> = {
      [PHASES.READ]: 'read',
      [PHASES.BLIND_RECALL]: 'recall',
      [PHASES.SUMMARY]: 'summary',
      [PHASES.REVISION]: 'revision',
      [PHASES.QUIZ]: 'quiz',
      [PHASES.FEEDBACK]: 'feedback',
      [PHASES.COMPLETED]: 'feedback',
    }
    return phaseToTab[phase] || 'read'
  }

  function isTabAccessible(tab: Tab): boolean {
    const tabPhase = TAB_TO_PHASE[tab]
    return canAccessPhase(currentPhase, tabPhase)
  }

  function handleTabClick(tab: Tab) {
    if (!isTabAccessible(tab)) return
    setActiveTab(tab)
  }

  // Load recall answers
  useEffect(() => {
    async function loadRecall() {
      try {
        const res = await fetch(`/api/section/${sectionId}/recall`)
        const json = await res.json()
        if (json.success && json.data.answers) {
          setRecallAnswers(json.data.answers)
          setIsRecallSubmitted(json.data.submitted)
        }
      } catch (err) {
        console.error('Failed to load recall:', err)
      } finally {
        setIsRecallLoading(false)
        setTimeout(() => { recallInitialLoadRef.current = false }, 100)
      }
    }
    loadRecall()
  }, [sectionId])

  // Load revision answers
  useEffect(() => {
    async function loadRevision() {
      try {
        const res = await fetch(`/api/section/${sectionId}/revision`)
        const json = await res.json()
        if (json.success && json.data.answers) {
          setRevisionAnswers(json.data.answers)
          setIsRevisionSubmitted(json.data.submitted)
        }
      } catch (err) {
        console.error('Failed to load revision:', err)
      } finally {
        setIsRevisionLoading(false)
        setTimeout(() => { revisionInitialLoadRef.current = false }, 100)
      }
    }
    loadRevision()
  }, [sectionId])

  // Load quiz
  useEffect(() => {
    async function loadQuiz() {
      try {
        const res = await fetch(`/api/section/${sectionId}/quiz`)
        const json = await res.json()
        if (json.success) {
          setQuestions(json.data.questions)
          setIsQuizSubmitted(json.data.submitted)
          const savedAnswers: Record<string, string> = {}
          json.data.questions.forEach((q: Question) => {
            if (q.savedAnswer) savedAnswers[q.id] = q.savedAnswer
          })
          setQuizAnswers(savedAnswers)
        }
      } catch (err) {
        console.error('Failed to load quiz:', err)
      } finally {
        setIsQuizLoading(false)
        setTimeout(() => { quizInitialLoadRef.current = false }, 100)
      }
    }
    loadQuiz()
  }, [sectionId])

  // Load evaluation
  useEffect(() => {
    async function loadEvaluation() {
      try {
        const res = await fetch(`/api/section/${sectionId}/evaluate`)
        const json = await res.json()
        if (json.success && json.data.evaluated) {
          setEvaluation(json.data)
          if (json.data.phase) setCurrentPhase(json.data.phase as Phase)
        }
      } catch (err) {
        console.error('Failed to load evaluation:', err)
      }
    }
    loadEvaluation()
  }, [sectionId])

  // Recall autosave
  const saveRecall = useCallback(async (answers: RecallAnswers, submit = false) => {
    setRecallSaveStatus('saving')
    try {
      const res = await fetch(`/api/section/${sectionId}/recall`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ answers, submit }),
      })
      const json = await res.json()
      if (json.success) {
        setRecallSaveStatus('saved')
        if (submit) {
          setIsRecallSubmitted(true)
          setCurrentPhase(PHASES.SUMMARY)
          setActiveTab('summary')
          router.refresh()
        }
        setTimeout(() => setRecallSaveStatus('idle'), 2000)
      } else {
        setRecallSaveStatus('error')
      }
    } catch {
      setRecallSaveStatus('error')
    }
  }, [sectionId, router])

  useEffect(() => {
    if (recallInitialLoadRef.current || isRecallSubmitted) return
    if (recallSaveTimerRef.current) clearTimeout(recallSaveTimerRef.current)
    const hasContent = Object.values(recallAnswers).some((v) => v.trim())
    if (!hasContent) return
    recallSaveTimerRef.current = setTimeout(() => saveRecall(recallAnswers), AUTOSAVE_DELAY_MS)
    return () => { if (recallSaveTimerRef.current) clearTimeout(recallSaveTimerRef.current) }
  }, [recallAnswers, saveRecall, isRecallSubmitted])

  // Revision autosave
  const saveRevision = useCallback(async (answers: RevisionAnswers, submit = false) => {
    setRevisionSaveStatus('saving')
    try {
      const res = await fetch(`/api/section/${sectionId}/revision`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ answers, submit }),
      })
      const json = await res.json()
      if (json.success) {
        setRevisionSaveStatus('saved')
        if (submit) {
          setIsRevisionSubmitted(true)
          setCurrentPhase(PHASES.QUIZ)
          setActiveTab('quiz')
          router.refresh()
        }
        setTimeout(() => setRevisionSaveStatus('idle'), 2000)
      } else {
        setRevisionSaveStatus('error')
      }
    } catch {
      setRevisionSaveStatus('error')
    }
  }, [sectionId, router])

  useEffect(() => {
    if (revisionInitialLoadRef.current || isRevisionSubmitted) return
    if (revisionSaveTimerRef.current) clearTimeout(revisionSaveTimerRef.current)
    const hasContent = Object.values(revisionAnswers).some((v) => v.trim())
    if (!hasContent) return
    revisionSaveTimerRef.current = setTimeout(() => saveRevision(revisionAnswers), AUTOSAVE_DELAY_MS)
    return () => { if (revisionSaveTimerRef.current) clearTimeout(revisionSaveTimerRef.current) }
  }, [revisionAnswers, saveRevision, isRevisionSubmitted])

  // Quiz autosave
  const saveQuiz = useCallback(async (answers: Record<string, string>, submit = false) => {
    setQuizSaveStatus('saving')
    try {
      const answersArray = Object.entries(answers).map(([questionId, answer]) => ({ questionId, answer }))
      const res = await fetch(`/api/section/${sectionId}/quiz`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ answers: answersArray, submit }),
      })
      const json = await res.json()
      if (json.success) {
        setQuizSaveStatus('saved')
        if (submit) setIsQuizSubmitted(true)
        setTimeout(() => setQuizSaveStatus('idle'), 2000)
      } else {
        setQuizSaveStatus('error')
      }
    } catch {
      setQuizSaveStatus('error')
    }
  }, [sectionId])

  useEffect(() => {
    if (quizInitialLoadRef.current || isQuizSubmitted) return
    if (quizSaveTimerRef.current) clearTimeout(quizSaveTimerRef.current)
    const hasContent = Object.values(quizAnswers).some((v) => v?.trim())
    if (!hasContent) return
    quizSaveTimerRef.current = setTimeout(() => saveQuiz(quizAnswers), AUTOSAVE_DELAY_MS)
    return () => { if (quizSaveTimerRef.current) clearTimeout(quizSaveTimerRef.current) }
  }, [quizAnswers, saveQuiz, isQuizSubmitted])

  // Load user reading level preference
  useEffect(() => {
    async function loadReadingLevel() {
      try {
        const res = await fetch('/api/user/preferences')
        const json = await res.json()
        if (json.success) {
          setReadingLevel(json.data.readingLevel)
        }
      } catch (err) {
        console.error('Failed to load reading level:', err)
      }
    }
    loadReadingLevel()
  }, [])

  // Cleanup EventSource on unmount
  useEffect(() => {
    return () => {
      if (eventSourceRef.current) {
        eventSourceRef.current.close()
      }
    }
  }, [])

  // Phase advancement handlers
  function handleFinishReading() {
    if (getPhaseIndex(currentPhase) < getPhaseIndex(PHASES.BLIND_RECALL)) {
      setCurrentPhase(PHASES.BLIND_RECALL)
    }
    setActiveTab('recall')
  }

  function handleSubmitRecall() {
    if (recallSaveTimerRef.current) clearTimeout(recallSaveTimerRef.current)
    saveRecall(recallAnswers, true)
  }

  function handleFinishSummary() {
    if (getPhaseIndex(currentPhase) < getPhaseIndex(PHASES.REVISION)) {
      setCurrentPhase(PHASES.REVISION)
    }
    setActiveTab('revision')
  }

  function handleSubmitRevision() {
    if (revisionSaveTimerRef.current) clearTimeout(revisionSaveTimerRef.current)
    saveRevision(revisionAnswers, true)
  }

  function handleSubmitQuiz() {
    if (quizSaveTimerRef.current) clearTimeout(quizSaveTimerRef.current)
    saveQuiz(quizAnswers, true)
  }

  async function handleEvaluate() {
    setIsEvaluating(true)
    try {
      const res = await fetch(`/api/section/${sectionId}/evaluate`, { method: 'POST' })
      const json = await res.json()
      if (json.success) {
        setEvaluation({ evaluated: true, recall: json.data.recall, quiz: json.data.quiz })
        setCurrentPhase(PHASES.FEEDBACK)
        setActiveTab('feedback')
        router.refresh()
      } else {
        alert('Evaluation failed: ' + json.error)
      }
    } catch (err) {
      alert('Evaluation failed: ' + (err instanceof Error ? err.message : 'Unknown error'))
    } finally {
      setIsEvaluating(false)
    }
  }

  // Helper for localStorage key
  const getProgressKey = (level: string) => `simplified-progress-${sectionId}-${level}`

  async function handleSimplifiedClick() {
    if (readView === 'simplified') {
      setReadView('original')
      return
    }

    // Close any existing stream before starting new one
    if (eventSourceRef.current) {
      eventSourceRef.current.close()
      eventSourceRef.current = null
    }

    setReadView('simplified')
    setSimplifyError(null)
    setSimplifiedContent('') // Clear stale content

    // Re-fetch reading level to get latest preference
    let currentLevel = readingLevel
    try {
      const prefRes = await fetch('/api/user/preferences')
      const prefJson = await prefRes.json()
      if (prefJson.success) {
        currentLevel = prefJson.data.readingLevel
        setReadingLevel(currentLevel)
      }
    } catch (err) {
      console.error('Failed to fetch reading level:', err)
    }

    // Check server cache first
    try {
      const cacheRes = await fetch(`/api/section/${sectionId}/simplified?level=${currentLevel}`)
      const cacheJson = await cacheRes.json()

      if (cacheJson.success && cacheJson.data.cached) {
        setSimplifiedContent(cacheJson.data.content)
        setSimplifyStatus('ready')
        // Clear any partial progress from localStorage
        localStorage.removeItem(getProgressKey(currentLevel))
        return
      }
    } catch (err) {
      console.error('Cache check failed:', err)
    }

    // Check localStorage for partial progress (from previous interrupted session)
    const progressKey = getProgressKey(currentLevel)
    try {
      const savedProgress = localStorage.getItem(progressKey)
      if (savedProgress) {
        const { paragraphs, total } = JSON.parse(savedProgress)
        if (paragraphs && paragraphs.length > 0) {
          setSimplifiedParagraphs(paragraphs)
          setTotalParagraphs(total)
          setSimplifyStatus('loading')
          // Continue streaming from where we left off (server may have finished)
        }
      }
    } catch (err) {
      console.error('Failed to load progress from localStorage:', err)
    }

    // Stream generation
    setSimplifyStatus('loading')
    if (!simplifiedParagraphs.length) {
      setSimplifiedParagraphs([])
      setTotalParagraphs(0)
    }

    try {
      const eventSource = new EventSource(
        `/api/section/${sectionId}/simplified/stream?level=${currentLevel}`
      )
      eventSourceRef.current = eventSource

      eventSource.onmessage = (event) => {
        const data = JSON.parse(event.data)

        if (data.error) {
          setSimplifyError(data.error)
          setSimplifyStatus('error')
          eventSource.close()
          eventSourceRef.current = null
          return
        }

        if (data.total !== undefined) {
          setTotalParagraphs(data.total)
          // Save total to localStorage immediately
          try {
            const existing = localStorage.getItem(progressKey)
            const parsed = existing ? JSON.parse(existing) : { paragraphs: [] }
            localStorage.setItem(progressKey, JSON.stringify({ ...parsed, total: data.total }))
          } catch (e) {
            // ignore
          }
        }

        if (data.paragraph !== undefined && data.text) {
          setSimplifiedParagraphs((prev) => {
            const updated = [...prev]
            updated[data.paragraph] = data.text
            // Save progress to localStorage
            try {
              const existing = localStorage.getItem(progressKey)
              const existingTotal = existing ? JSON.parse(existing).total : updated.length
              localStorage.setItem(progressKey, JSON.stringify({
                paragraphs: updated,
                total: existingTotal
              }))
            } catch (e) {
              // localStorage might be full, ignore
            }
            return updated
          })
        }

        if (data.done) {
          setSimplifyStatus('ready')
          // Clear localStorage - server has cached the complete content
          localStorage.removeItem(progressKey)
          eventSource.close()
          eventSourceRef.current = null
        }
      }

      eventSource.onerror = () => {
        setSimplifyError('Connection lost. Please try again.')
        setSimplifyStatus('error')
        eventSource.close()
        eventSourceRef.current = null
      }
    } catch (err) {
      setSimplifyError(err instanceof Error ? err.message : 'Failed to generate')
      setSimplifyStatus('error')
    }
  }

  const getSaveStatusDisplay = (status: SaveStatus) => {
    switch (status) {
      case 'saving': return <span className="text-gray-500">Saving...</span>
      case 'saved': return <span className="text-green-600">Saved</span>
      case 'error': return <span className="text-red-600">Save failed</span>
      default: return null
    }
  }

  const LockIcon = () => (
    <svg className="w-3 h-3 ml-1" fill="currentColor" viewBox="0 0 20 20">
      <path fillRule="evenodd" d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z" clipRule="evenodd" />
    </svg>
  )

  const CheckIcon = () => (
    <svg className="w-3 h-3 ml-1" fill="currentColor" viewBox="0 0 20 20">
      <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
    </svg>
  )

  return (
    <div>
      {/* Phase indicator */}
      <div className="mb-4 text-sm text-gray-500">
        Phase: <span className="font-medium text-gray-700 capitalize">{currentPhase.replace('_', ' ')}</span>
      </div>

      {/* Tab navigation with locks */}
      <div className="flex gap-1 mb-6 border-b overflow-x-auto">
        {TABS.map((tab) => {
          const isAccessible = isTabAccessible(tab.id)
          const isActive = activeTab === tab.id
          const isCompleted = getPhaseIndex(currentPhase) > getPhaseIndex(tab.phase)

          return (
            <button
              key={tab.id}
              onClick={() => handleTabClick(tab.id)}
              disabled={!isAccessible}
              className={`px-4 py-2 text-sm font-medium transition-colors whitespace-nowrap flex items-center ${
                isActive ? 'border-b-2 border-blue-500 text-blue-600'
                  : isAccessible ? 'text-gray-600 hover:text-gray-800'
                  : 'text-gray-300 cursor-not-allowed'
              }`}
              title={!isAccessible ? `Complete ${currentPhase.replace('_', ' ')} first` : undefined}
            >
              {tab.label}
              {!isAccessible && <LockIcon />}
              {isCompleted && isAccessible && <CheckIcon />}
            </button>
          )
        })}
      </div>

      {/* Tab content */}
      <div className="border rounded-lg p-6">
        {/* READ */}
        {activeTab === 'read' && (
          <div>
            {/* View toggle */}
            <div className="flex items-center gap-4 mb-6">
              <div className="flex rounded-lg border overflow-hidden">
                <button
                  onClick={() => setReadView('original')}
                  className={`px-4 py-2 text-sm font-medium transition-colors ${
                    readView === 'original'
                      ? 'bg-blue-600 text-white'
                      : 'bg-white text-gray-600 hover:bg-gray-50'
                  }`}
                >
                  Original
                </button>
                <button
                  onClick={handleSimplifiedClick}
                  className={`px-4 py-2 text-sm font-medium transition-colors ${
                    readView === 'simplified'
                      ? 'bg-blue-600 text-white'
                      : 'bg-white text-gray-600 hover:bg-gray-50'
                  }`}
                >
                  Simplified
                </button>
              </div>
              {readView === 'simplified' && simplifyStatus === 'ready' && (
                <span className="text-sm text-gray-500 bg-gray-100 px-2 py-1 rounded capitalize">
                  {readingLevel}
                </span>
              )}
              {readView === 'simplified' && simplifyStatus === 'loading' && (
                <span className="text-sm text-blue-600">
                  Simplifying... {simplifiedParagraphs.length}/{totalParagraphs || '?'}
                </span>
              )}
            </div>

            {/* Content display */}
            <div className="prose max-w-none mb-6">
              {readView === 'original' ? (
                <div className="whitespace-pre-wrap font-serif text-lg leading-relaxed">
                  {sectionContent || 'No content available.'}
                </div>
              ) : simplifyStatus === 'error' ? (
                <div className="bg-red-50 border border-red-200 rounded-lg p-4">
                  <p className="text-red-800 mb-2">{simplifyError}</p>
                  <button
                    onClick={handleSimplifiedClick}
                    className="text-sm text-red-600 hover:underline"
                  >
                    Try again
                  </button>
                </div>
              ) : simplifyStatus === 'loading' ? (
                <div className="space-y-4">
                  {simplifiedParagraphs.map((text, idx) => (
                    <p key={idx} className="font-serif text-lg leading-relaxed">
                      {text}
                    </p>
                  ))}
                  {simplifiedParagraphs.length < totalParagraphs && (
                    <div className="animate-pulse">
                      <div className="h-4 bg-gray-200 rounded w-full mb-2"></div>
                      <div className="h-4 bg-gray-200 rounded w-5/6"></div>
                    </div>
                  )}
                </div>
              ) : simplifyStatus === 'ready' ? (
                <div className="whitespace-pre-wrap font-serif text-lg leading-relaxed">
                  {simplifiedContent || simplifiedParagraphs.join('\n\n')}
                </div>
              ) : (
                <div className="text-gray-500 text-center py-8">
                  Click "Simplified" to generate an easier-to-read version.
                </div>
              )}
            </div>

            <div className="border-t pt-4">
              <button onClick={handleFinishReading} className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">
                I've finished reading → Continue to Recall
              </button>
            </div>
          </div>
        )}

        {/* RECALL */}
        {activeTab === 'recall' && (
          <div>
            <div className="mb-6">
              <h3 className="text-lg font-semibold mb-2">Blind Recall</h3>
              <p className="text-gray-600 text-sm">Without looking back, answer from memory.</p>
            </div>
            {isRecallLoading ? (
              <div className="text-gray-500 text-center py-8">Loading...</div>
            ) : isRecallSubmitted ? (
              <div className="bg-green-50 border border-green-200 rounded-lg p-6">
                <h4 className="font-medium text-green-800 mb-4">Recall Submitted!</h4>
                <div className="space-y-4">
                  {RECALL_PROMPTS.map((prompt) => (
                    <div key={prompt.id} className="border-l-4 border-green-200 pl-4">
                      <span className="font-medium">{prompt.title}</span>
                      <p className="text-gray-700 mt-1 whitespace-pre-wrap">
                        {recallAnswers[prompt.id] || <span className="text-gray-400 italic">No answer</span>}
                      </p>
                    </div>
                  ))}
                </div>
                <div className="mt-6 border-t pt-4">
                  <button onClick={() => setActiveTab('summary')} className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">
                    Continue to Summary →
                  </button>
                </div>
              </div>
            ) : (
              <>
                <div className="space-y-6">
                  {RECALL_PROMPTS.map((prompt) => (
                    <div key={prompt.id} className="border-l-4 border-blue-200 pl-4">
                      <label className="block">
                        <span className="font-medium">{prompt.title}</span>
                        <span className="block text-sm text-gray-600 mb-2">{prompt.question}</span>
                        <textarea
                          className="w-full p-3 border rounded-lg resize-none text-sm"
                          rows={3}
                          placeholder={prompt.placeholder}
                          value={recallAnswers[prompt.id]}
                          onChange={(e) => setRecallAnswers((prev) => ({ ...prev, [prompt.id]: e.target.value }))}
                        />
                      </label>
                    </div>
                  ))}
                </div>
                <div className="mt-6 flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <span className="text-sm text-gray-500">{Object.values(recallAnswers).filter((v) => v.trim()).length} of 5 answered</span>
                    {getSaveStatusDisplay(recallSaveStatus)}
                  </div>
                  <button
                    className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50"
                    onClick={handleSubmitRecall}
                    disabled={recallSaveStatus === 'saving' || Object.values(recallAnswers).filter((v) => v.trim()).length === 0}
                  >
                    Submit Recall & Continue
                  </button>
                </div>
              </>
            )}
          </div>
        )}

        {/* SUMMARY */}
        {activeTab === 'summary' && (
          <div>
            <div className="prose max-w-none mb-6">
              <h3 className="text-lg font-semibold mb-4">Summary</h3>
              {summaryContent ? (
                <div className="whitespace-pre-wrap">{summaryContent}</div>
              ) : (
                <p className="text-gray-500">Summary not yet generated.</p>
              )}
            </div>
            {summaryContent && (
              <div className="border-t pt-4">
                <button onClick={handleFinishSummary} className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">
                  I've reviewed the summary → Continue to Revision
                </button>
              </div>
            )}
          </div>
        )}

        {/* REVISION */}
        {activeTab === 'revision' && (
          <div>
            <div className="mb-6">
              <h3 className="text-lg font-semibold mb-2">Revision</h3>
              <p className="text-gray-600 text-sm">Compare your recall with the summary. What did you miss?</p>
            </div>
            {isRevisionLoading ? (
              <div className="text-gray-500 text-center py-8">Loading...</div>
            ) : isRevisionSubmitted ? (
              <div className="bg-green-50 border border-green-200 rounded-lg p-6">
                <h4 className="font-medium text-green-800 mb-4">Revision Submitted!</h4>
                <div className="space-y-4">
                  {REVISION_PROMPTS.map((prompt) => (
                    <div key={prompt.id} className="border-l-4 border-green-200 pl-4">
                      <span className="font-medium">{prompt.title}</span>
                      <p className="text-gray-700 mt-1 whitespace-pre-wrap">
                        {revisionAnswers[prompt.id] || <span className="text-gray-400 italic">No answer</span>}
                      </p>
                    </div>
                  ))}
                </div>
                <div className="mt-6 border-t pt-4">
                  <button onClick={() => setActiveTab('quiz')} className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700">
                    Continue to Quiz →
                  </button>
                </div>
              </div>
            ) : (
              <>
                <div className="space-y-6">
                  {REVISION_PROMPTS.map((prompt) => (
                    <div key={prompt.id} className="border-l-4 border-amber-200 pl-4">
                      <label className="block">
                        <span className="font-medium">{prompt.title}</span>
                        <span className="block text-sm text-gray-600 mb-2">{prompt.question}</span>
                        <textarea
                          className="w-full p-3 border rounded-lg resize-none text-sm"
                          rows={3}
                          placeholder={prompt.placeholder}
                          value={revisionAnswers[prompt.id]}
                          onChange={(e) => setRevisionAnswers((prev) => ({ ...prev, [prompt.id]: e.target.value }))}
                        />
                      </label>
                    </div>
                  ))}
                </div>
                <div className="mt-6 flex items-center justify-between">
                  <div className="flex items-center gap-4">
                    <span className="text-sm text-gray-500">{Object.values(revisionAnswers).filter((v) => v.trim()).length} of 3 answered</span>
                    {getSaveStatusDisplay(revisionSaveStatus)}
                  </div>
                  <button
                    className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50"
                    onClick={handleSubmitRevision}
                    disabled={revisionSaveStatus === 'saving' || Object.values(revisionAnswers).filter((v) => v.trim()).length === 0}
                  >
                    Submit Revision & Continue
                  </button>
                </div>
              </>
            )}
          </div>
