              <div className="space-y-6">
                <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                  <p className="text-blue-800">Quiz evaluated! Score: {evaluation.quiz?.totalScore ?? 0}/{questions.length}</p>
                </div>
                {questions.map((q, idx) => {
                  const feedbackData = evaluation.quiz?.answers.find(a => a.questionId === q.id)
                  return (
                    <div key={q.id} className="border rounded-lg p-4">
                      <div className="flex items-start gap-2 mb-3">
                        <span className="text-sm font-medium text-gray-500">{idx + 1}.</span>
                        <div className="flex-1">
                          <p className="font-medium">{q.questionText}</p>
                        </div>
                        {feedbackData && (
                          <span className={`px-2 py-1 rounded text-xs font-medium ${feedbackData.score >= 1 ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                            {feedbackData.score}/1
                          </span>
                        )}
                      </div>
                      <div className="bg-gray-50 p-3 rounded text-sm">{quizAnswers[q.id] || 'No answer'}</div>
                    </div>
