import { prisma } from '@/lib/db'
import { getDefaultUser } from '@/lib/user'
import { NextResponse } from 'next/server'
import { PHASES } from '@/lib/constants'

interface RevisionAnswers {
  forgottenPoints: string
  misremembered: string
  missedExamples: string
}

/**
 * GET /api/section/[id]/revision
 * Load saved revision answers for a section
 */
export async function GET(_req: Request, { params }: { params: { id: string } }) {
  try {
    const user = await getDefaultUser()

    const attempt = await prisma.sectionAttempt.findUnique({
      where: {
        userId_sectionId: {
          userId: user.id,
          sectionId: params.id,
        },
      },
      select: {
        missedPoints: true,
        missedSubmittedAt: true,
        currentPhase: true,
      },
    })

    if (!attempt || !attempt.missedPoints) {
      return NextResponse.json({
        success: true,
        data: {
          answers: null,
          submitted: false,
        },
      })
    }

    const answers = JSON.parse(attempt.missedPoints) as RevisionAnswers

    return NextResponse.json({
      success: true,
      data: {
        answers,
        submitted: !!attempt.missedSubmittedAt,
        phase: attempt.currentPhase,
      },
    })
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to load revision answers'
    return NextResponse.json({ success: false, error: message }, { status: 500 })
  }
}

/**
 * PUT /api/section/[id]/revision
 * Save revision answers (autosave or explicit submit)
 */
export async function PUT(req: Request, { params }: { params: { id: string } }) {
  try {
    const body = await req.json()
    const { answers, submit } = body as { answers: RevisionAnswers; submit?: boolean }

    if (!answers) {
      return NextResponse.json({ success: false, error: 'answers required' }, { status: 400 })
    }

    const user = await getDefaultUser()

    // Verify section exists
    const section = await prisma.section.findUnique({
      where: { id: params.id },
    })

    if (!section) {
      return NextResponse.json({ success: false, error: 'Section not found' }, { status: 404 })
    }

    // Update SectionAttempt with revision answers
    const updateData: {
      missedPoints: string
      missedSubmittedAt?: Date
      currentPhase?: string
    } = {
      missedPoints: JSON.stringify(answers),
    }

    // If explicitly submitting, mark as submitted and advance phase
    if (submit) {
      updateData.missedSubmittedAt = new Date()
      updateData.currentPhase = PHASES.QUIZ
    }

    await prisma.sectionAttempt.update({
      where: {
        userId_sectionId: {
          userId: user.id,
          sectionId: params.id,
        },
      },
      data: updateData,
    })

    return NextResponse.json({
      success: true,
      data: {
        saved: true,
        submitted: !!submit,
      },
    })
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to save revision answers'
    return NextResponse.json({ success: false, error: message }, { status: 500 })
  }
}

