import { prisma } from '@/lib/db'
import { getDefaultUser } from '@/lib/user'
import { NextResponse } from 'next/server'
import { generateText } from '@/lib/ai/azure'
import { loadPrompt } from '@/lib/prompts/registry'
import { PHASES } from '@/lib/constants'

interface RecallAnswers {
  mainClaim: string
  keyMechanism: string
  example: string
  modernParallel: string
  uncertainty: string
}

interface EvaluationResult {
  recall?: {
    points: Array<{
      label: string
      correct: boolean
      accuracy: string
      reasoning: string
      writing: string
    }>
    one_sentence_ok: boolean
    one_sentence_note: string
    score: number
    reasoning: string
  }
  quiz?: {
    answers: Array<{
      question_id: string
      label: string
