export type ParsedQuestion = {
  questionType: 'mcq' | 'prose'
  questionSubtype: string
  questionText: string
  options?: string[]
  correctAnswer?: string
}

export function parseQuizMarkdown(markdown: string): ParsedQuestion[] {
  const blocks = markdown.split(/\n---\n/g)
  const questions: ParsedQuestion[] = []

  for (const block of blocks) {
    const mcqMatch = block.match(/\*\*Type:\*\*\s*(one|multiple|none)/i)
    if (mcqMatch) {
      const options = Array.from(block.matchAll(/-\s+[A-D]\)\s+(.+)/g)).map(m => m[1].trim())
      const correct = block.match(/\*\*Correct:\*\*\s*([^\n]+)/i)?.[1]?.trim()
      const lines = block.split('\n')
      // Exclude ALL headings (# prefix), not just ### - for consistency with prose parser
      const qLine = lines.find(line => line.trim() && !line.startsWith('#') && !line.startsWith('-') && !line.startsWith('**') && !line.startsWith('<'))
      questions.push({
        questionType: 'mcq',
        questionSubtype: mcqMatch[1].toLowerCase(),
        questionText: qLine?.trim() ?? '',
        options,
        correctAnswer: correct,
      })
      continue
    }

    // Match prose questions - either "[Type: Adversarial]" or just "### N. Adversarial"
    const proseMatch = block.match(/\[Type:\s*(Adversarial|Comparative|Socratic|Synthesis)\]/i)
      || block.match(/###\s*\d+\.\s*(Adversarial|Comparative|Socratic|Synthesis)\b/i)
    if (proseMatch) {
      const lines = block.split('\n')
      // Exclude ALL headings (# prefix), not just ### - fixes "## Part B" being picked as question text
      const qLine = lines.find(line => line.trim() && !line.startsWith('#') && !line.startsWith('**') && !line.startsWith('[Type'))
      const questionText = qLine?.trim() ?? ''
      // Skip if no actual question text found (e.g., section headers without questions)
      if (questionText) {
        questions.push({
          questionType: 'prose',
          questionSubtype: proseMatch[1].toLowerCase(),
          questionText,
        })
      }
    }
  }

  return questions
}

