import { prisma } from '@/lib/db'
import { getDefaultUser } from '@/lib/user'
import { loadPrompt } from '@/lib/prompts/registry'
import { generateText } from '@/lib/ai/azure'
import { parseQuizMarkdown } from '@/lib/prompts/quizParser'
import { PHASES } from '@/lib/constants'

interface ProgressEvent {
  step: number
  totalSteps: number
  message: string
  status: 'in_progress' | 'complete' | 'error'
  error?: string
}

function createSSEStream() {
  const encoder = new TextEncoder()
  let controller: ReadableStreamDefaultController<Uint8Array>

  const stream = new ReadableStream<Uint8Array>({
    start(c) {
      controller = c
    },
  })

  function send(event: ProgressEvent) {
    const data = `data: ${JSON.stringify(event)}\n\n`
    controller.enqueue(encoder.encode(data))
  }

  function close() {
    controller.close()
  }

  return { stream, send, close }
}

export async function POST(_req: Request, { params }: { params: { id: string } }) {
  const { stream, send, close } = createSSEStream()

  // Run generation in background, streaming progress
  ;(async () => {
    try {
      send({ step: 1, totalSteps: 5, message: 'Checking prerequisites...', status: 'in_progress' })

      const user = await getDefaultUser()

      const section = await prisma.section.findUnique({
        where: { id: params.id },
        include: { book: true },
      })

      if (!section || !section.book) {
        send({ step: 1, totalSteps: 5, message: 'Section not found', status: 'error', error: 'Section not found' })
        close()
        return
      }

      // Check if previous section is completed (if not section 1)
      if (section.sectionNumber > 1) {
        const previousSection = await prisma.section.findFirst({
          where: {
            bookId: section.bookId,
            sectionNumber: section.sectionNumber - 1,
          },
        })

        if (previousSection) {
          const previousAttempt = await prisma.sectionAttempt.findUnique({
            where: {
              userId_sectionId: {
                userId: user.id,
                sectionId: previousSection.id,
              },
            },
          })

          if (!previousAttempt || previousAttempt.currentPhase !== PHASES.COMPLETED) {
            send({
              step: 1,
              totalSteps: 5,
              message: 'Complete the previous section first',
              status: 'error',
              error: 'Previous section not completed',
            })
            close()
            return
          }
        }
      }

      // Create or get existing SectionAttempt
      await prisma.sectionAttempt.upsert({
        where: {
          userId_sectionId: {
            userId: user.id,
            sectionId: section.id,
          },
        },
        create: {
          userId: user.id,
          sectionId: section.id,
          currentPhase: PHASES.READ,
        },
        update: {}, // Don't update if already exists
      })

      send({ step: 2, totalSteps: 5, message: 'Generating summary...', status: 'in_progress' })

      const summaryPrompt = loadPrompt('summary')
      const summaryText = summaryPrompt.template
        .replaceAll('{book_title}', section.book.title)
        .replaceAll('{author}', section.book.author)
        .replaceAll('{section_id}', String(section.sectionNumber).padStart(3, '0'))
        .replaceAll('{section_title}', section.title)
        .replaceAll('{location}', section.location)
        .replaceAll('{source_text}', section.sectionContent ?? '')
        .replaceAll('{model}', process.env.AZURE_AI_MODEL ?? 'claude-opus-4-5')
        .replaceAll('{date}', new Date().toISOString().slice(0, 10))

      const summaryOut = await generateText({ prompt: summaryText })

      send({ step: 3, totalSteps: 5, message: 'Generating quiz questions...', status: 'in_progress' })

      const quizPrompt = loadPrompt('quiz')
      const quizText = quizPrompt.template
        .replaceAll('{book_title}', section.book.title)
        .replaceAll('{author}', section.book.author)
        .replaceAll('{section_id}', String(section.sectionNumber).padStart(3, '0'))
        .replaceAll('{section_title}', section.title)
        .replaceAll('{location}', section.location)
        .replaceAll('{summary_text}', summaryOut)
        .replaceAll('{source_text}', section.sectionContent ?? '')

      const quizOut = await generateText({ prompt: quizText })
      console.log('[Quiz Generation] Raw output (first 2000):', quizOut.substring(0, 2000))
      console.log('[Quiz Generation] Part B section:', quizOut.substring(quizOut.indexOf('Part B'), quizOut.indexOf('Part B') + 1500))
      console.log('[Quiz Generation] Contains Part B:', quizOut.includes('Part B'))
      const parsed = parseQuizMarkdown(quizOut)
