              {summaryView === 'detailed' && detailedStatus === 'loading' && (
                <span className="text-sm text-blue-600">
                  Condensing... {detailedParagraphs.filter(Boolean).length}/{detailedTotal || '?'}
                </span>
              )}
            </div>

            {/* Quick Review */}
            {summaryView === 'quick' && (
