```typescript
import { describe, it, expect, beforeAll, afterAll } from 'vitest'
import { PrismaClient } from '@prisma/client'

// Test database client
const TEST_DATABASE_URL = process.env.TEST_DATABASE_URL ||
  "sqlserver://localhost:1433;database=edps_test;user=sa;password=EdpsLocal#2024;encrypt=true;trustServerCertificate=true"

const prisma = new PrismaClient({
  datasources: { db: { url: TEST_DATABASE_URL } }
})

// Get section 001 of wealth-of-nations
async function getTestSection() {
  const book = await prisma.book.findUnique({ where: { slug: 'wealth-of-nations' } })
  if (!book) throw new Error('Test book not found - run test db setup first')

  const section = await prisma.section.findFirst({
    where: { bookId: book.id, sectionNumber: 1 }
  })
  if (!section) throw new Error('Test section not found')

  return section
}

describe('Summary API E2E', () => {
  let sectionId: string

  beforeAll(async () => {
    const section = await getTestSection()
    sectionId = section.id

    // Clear any existing generated content for clean test
    await prisma.section.update({
      where: { id: sectionId },
      data: { summaryContent: null, detailedSummaryContent: null }
    })
  })

  afterAll(async () => {
    await prisma.$disconnect()
  })

  describe('POST /api/section/[id]/generate', () => {
    it('generates summary in JSON format', async () => {
      // Call the generate endpoint
      const response = await fetch(`http://localhost:3000/api/section/${sectionId}/generate`, {
        method: 'POST'
      })

      expect(response.ok).toBe(true)

      // Wait for SSE stream to complete
      const reader = response.body?.getReader()
      if (!reader) throw new Error('No response body')

      let lastEvent: any
      const decoder = new TextDecoder()

      while (true) {
        const { done, value } = await reader.read()
        if (done) break

        const text = decoder.decode(value)
        const lines = text.split('\n').filter(l => l.startsWith('data: '))
        for (const line of lines) {
          lastEvent = JSON.parse(line.replace('data: ', ''))
        }
      }

      expect(lastEvent.status).toBe('complete')

      // Verify summary is valid JSON
      const section = await prisma.section.findUnique({
        where: { id: sectionId },
        select: { summaryContent: true }
      })

      expect(section?.summaryContent).toBeTruthy()

      const summary = JSON.parse(section!.summaryContent!)

      // Assert structure
      expect(summary).toHaveProperty('tldr')
      expect(summary).toHaveProperty('keyTerms')
      expect(summary).toHaveProperty('argumentStructure')
      expect(summary).toHaveProperty('modernApplication')
      expect(summary).toHaveProperty('sourcePointers')

      expect(summary.keyTerms.length).toBeGreaterThanOrEqual(3)
      expect(summary.argumentStructure.length).toBeGreaterThanOrEqual(3)
      expect(summary.sourcePointers).toHaveProperty('keyPassage')
      expect(summary.sourcePointers).toHaveProperty('bestExample')
      expect(summary.sourcePointers).toHaveProperty('strongestArgument')
    }, 120000) // 2 minute timeout for AI generation
  })

  describe('GET /api/section/[id]/detailed/stream', () => {
    it('streams paragraph-by-paragraph condensation', async () => {
      const response = await fetch(`http://localhost:3000/api/section/${sectionId}/detailed/stream`)

      expect(response.ok).toBe(true)
      expect(response.headers.get('content-type')).toContain('text/event-stream')

      const reader = response.body?.getReader()
      if (!reader) throw new Error('No response body')

      const decoder = new TextDecoder()
      const events: any[] = []

      while (true) {
        const { done, value } = await reader.read()
        if (done) break

        const text = decoder.decode(value)
        const lines = text.split('\n').filter(l => l.startsWith('data: '))
        for (const line of lines) {
          events.push(JSON.parse(line.replace('data: ', '')))
        }
      }

      // Should have total, paragraph events, and done
      const totalEvent = events.find(e => e.total !== undefined)
      const paragraphEvents = events.filter(e => e.paragraph !== undefined)
      const doneEvent = events.find(e => e.done === true)

      expect(totalEvent).toBeTruthy()
      expect(paragraphEvents.length).toBe(totalEvent.total)
      expect(doneEvent).toBeTruthy()

      // Verify cached in database
      const section = await prisma.section.findUnique({
        where: { id: sectionId },
        select: { detailedSummaryContent: true }
      })

      expect(section?.detailedSummaryContent).toBeTruthy()
      expect(section!.detailedSummaryContent!.length).toBeGreaterThan(100)
    }, 180000) // 3 minute timeout for paragraph-by-paragraph

    it('returns cached content on second call', async () => {
      const response = await fetch(`http://localhost:3000/api/section/${sectionId}/detailed/stream`)

      const reader = response.body?.getReader()
      if (!reader) throw new Error('No response body')

      const decoder = new TextDecoder()
      const events: any[] = []

      while (true) {
        const { done, value } = await reader.read()
        if (done) break

        const text = decoder.decode(value)
        const lines = text.split('\n').filter(l => l.startsWith('data: '))
        for (const line of lines) {
          events.push(JSON.parse(line.replace('data: ', '')))
        }
      }

      // Should return cached immediately
      expect(events.length).toBe(1)
      expect(events[0].cached).toBe(true)
      expect(events[0].done).toBe(true)
    }, 5000) // Should be fast since cached
  })
})
```

