```typescript
export interface KeyTerm {
  term: string
  definition: string
}

export interface SourcePointers {
  keyPassage: string
  bestExample: string
  strongestArgument: string
}

export interface QuickSummary {
  tldr: string
  keyTerms: KeyTerm[]
  argumentStructure: string[]
  modernApplication: string
  sourcePointers: SourcePointers
}

/**
 * Parse JSON summary from AI output.
 * Handles both raw JSON and markdown-wrapped JSON (```json ... ```)
 */
export function parseSummaryJson(input: string): QuickSummary | null {
  try {
    // Extract JSON from markdown code block if present
    const jsonMatch = input.match(/```json\s*([\s\S]*?)\s*```/)
    const jsonStr = jsonMatch ? jsonMatch[1] : input

    const parsed = JSON.parse(jsonStr)

    // Validate required fields
    if (
      typeof parsed.tldr !== 'string' ||
      !Array.isArray(parsed.keyTerms) ||
      !Array.isArray(parsed.argumentStructure) ||
      typeof parsed.modernApplication !== 'string' ||
      typeof parsed.sourcePointers !== 'object'
    ) {
      return null
    }

    return {
      tldr: parsed.tldr,
      keyTerms: parsed.keyTerms,
      argumentStructure: parsed.argumentStructure,
      modernApplication: parsed.modernApplication,
      sourcePointers: parsed.sourcePointers,
    }
  } catch {
    return null
  }
}

/**
 * Check if summary content is JSON format (new) or markdown (legacy)
 */
export function isJsonSummary(content: string): boolean {
  const trimmed = content.trim()
  return trimmed.startsWith('{') || trimmed.startsWith('```json')
}
```

