  async function handleDetailedClick() {
    // When toggling BACK to Quick Review, close any active SSE connection
    // This prevents background updates and wasted resources
    if (summaryView === 'detailed') {
      if (detailedEventSourceRef.current) {
        detailedEventSourceRef.current.close()
        detailedEventSourceRef.current = null
      }
      setSummaryView('quick')
      return
    }

    // Cleanup any existing EventSource before starting new one
    if (detailedEventSourceRef.current) {
      detailedEventSourceRef.current.close()
      detailedEventSourceRef.current = null
    }

    setSummaryView('detailed')
    setDetailedError(null)
    setDetailedContent('')
    setDetailedParagraphs([])
    setDetailedTotal(0)
    setDetailedStatus('loading')

    try {
      // Use POST with fetch (not EventSource) because:
      // 1. EventSource only supports GET
      // 2. This endpoint triggers AI generation (should be POST)
      // 3. We need AbortController support for cleanup
      const abortController = new AbortController()
      detailedAbortControllerRef.current = abortController

      const response = await fetch(`/api/section/${sectionId}/detailed/stream`, {
        method: 'POST',
        signal: abortController.signal,
      })

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`)
      }

      const reader = response.body?.getReader()
      if (!reader) throw new Error('No response body')

      const decoder = new TextDecoder()

      while (true) {
        const { done, value } = await reader.read()
        if (done) break

        const text = decoder.decode(value)
        const lines = text.split('\n').filter(l => l.startsWith('data: '))

        for (const line of lines) {
          const data = JSON.parse(line.replace('data: ', ''))

          if (data.error) {
            setDetailedError(data.error)
            setDetailedStatus('error')
            return
          }

          if (data.cached) {
            setDetailedContent(data.text)
            setDetailedStatus('ready')
            return
          }

          // Use != null to handle total: 0 edge case
          if (data.total != null) {
            setDetailedTotal(data.total)
          }

          if (data.paragraph !== undefined && data.text) {
            setDetailedParagraphs((prev) => {
              const updated = [...prev]
              updated[data.paragraph] = data.text
              return updated
            })
          }

          if (data.done) {
            setDetailedStatus('ready')
          }
        }
      }
    } catch (err) {
      // AbortError means user navigated away - not a real error
      if (err instanceof Error && err.name === 'AbortError') {
        console.log('[Detailed] Request aborted by user')
        return
      }
      setDetailedError(err instanceof Error ? err.message : 'Failed to load')
      setDetailedStatus('error')
    } finally {
      detailedAbortControllerRef.current = null
    }
  }
