interface LegacySummaryProps {
  content: string
}

/**
 * Renders legacy markdown summaries (pre-JSON format)
 * Strips metadata blocks and generation notes for cleaner display
 */
export function LegacySummary({ content }: LegacySummaryProps) {
  // Remove metadata lines (> Location:, > Generator:, etc.)
  // Remove Generation Notes section
  const cleaned = content
    .replace(/^>\s*(Location|Generator|Last updated):.*$/gm, '')
    .replace(/## Generation Notes[\s\S]*$/m, '')
    .replace(/^---$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim()

  return (
    <div className="prose max-w-none">
      <div className="whitespace-pre-wrap font-serif text-lg leading-relaxed">
        {cleaned}
      </div>
    </div>
  )
}
